// store.js

import { create } from "zustand";
import {
    addEdge,
    applyNodeChanges,
    applyEdgeChanges,
    MarkerType,
  } from 'reactflow';

export const useStore = create((set, get) => ({
    nodes: [
      {
        id: 'customInput-1',
        type: 'customInput',
        position: { x: 100, y: 100 },
        data: { inputName: 'system_prompt', inputType: 'Text' }
      },
      {
        id: 'customInput-2',
        type: 'customInput',
        position: { x: 100, y: 300 },
        data: { inputName: 'user_prompt', inputType: 'Text' }
      },
      {
        id: 'text-1',
        type: 'text',
        position: { x: 350, y: 150 },
        data: { text: 'System Instruction:\n{{system_prompt}}\n\nUser Question:\n{{user_prompt}}' }
      },
      {
        id: 'llm-1',
        type: 'llm',
        position: { x: 750, y: 200 },
        data: {}
      },
      {
        id: 'customOutput-1',
        type: 'customOutput',
        position: { x: 950, y: 200 },
        data: { outputName: 'final_result', outputType: 'Text' }
      }
    ],
    edges: [
      {
        id: 'e1',
        source: 'customInput-1',
        sourceHandle: 'customInput-1-value',
        target: 'text-1',
        targetHandle: 'text-1-system_prompt',
        type: 'smoothstep',
        animated: true,
        markerEnd: {type: MarkerType.Arrow, height: '20px', width: '20px'}
      },
      {
        id: 'e2',
        source: 'customInput-2',
        sourceHandle: 'customInput-2-value',
        target: 'text-1',
        targetHandle: 'text-1-user_prompt',
        type: 'smoothstep',
        animated: true,
        markerEnd: {type: MarkerType.Arrow, height: '20px', width: '20px'}
      },
      {
        id: 'e3',
        source: 'text-1',
        sourceHandle: 'text-1-output',
        target: 'llm-1',
        targetHandle: 'llm-1-prompt',
        type: 'smoothstep',
        animated: true,
        markerEnd: {type: MarkerType.Arrow, height: '20px', width: '20px'}
      },
      {
        id: 'e4',
        source: 'llm-1',
        sourceHandle: 'llm-1-response',
        target: 'customOutput-1',
        targetHandle: 'customOutput-1-value',
        type: 'smoothstep',
        animated: true,
        markerEnd: {type: MarkerType.Arrow, height: '20px', width: '20px'}
      }
    ],
    nodeIDs: {
        customInput: 2,
        text: 1,
        llm: 1,
        customOutput: 1
    },
    isDark: true,
    toggleTheme: () => set((state) => ({ isDark: !state.isDark })),
    getNodeID: (type) => {
        const newIDs = {...get().nodeIDs};
        if (newIDs[type] === undefined) {
            newIDs[type] = 0;
        }
        newIDs[type] += 1;
        set({nodeIDs: newIDs});
        return `${type}-${newIDs[type]}`;
    },
    addNode: (node) => {
        set({
            nodes: [...get().nodes, node]
        });
    },
    onNodesChange: (changes) => {
      set({
        nodes: applyNodeChanges(changes, get().nodes),
      });
    },
    onEdgesChange: (changes) => {
      set({
        edges: applyEdgeChanges(changes, get().edges),
      });
    },
    onConnect: (connection) => {
      set({
        edges: addEdge({...connection, type: 'smoothstep', animated: true, markerEnd: {type: MarkerType.Arrow, height: '20px', width: '20px'}}, get().edges),
      });
    },
    updateNodeField: (nodeId, fieldName, fieldValue) => {
      set({
        nodes: get().nodes.map((node) => {
          if (node.id === nodeId) {
            node.data = { ...node.data, [fieldName]: fieldValue };
          }

          return node;
        }),
      });
    },
    removeNode: (nodeId) => {
      set({
        nodes: get().nodes.filter((node) => node.id !== nodeId),
        edges: get().edges.filter((edge) => edge.source !== nodeId && edge.target !== nodeId),
      });
    },
  }));
